function renderMascotSvg(id, kind = 'pet') {
  const tpl = MASCOT_TEMPLATES[id];
  if (!tpl) return '';
  const raw = kind === 'bubble' ? (tpl.bubbleSvg || tpl.petSvg) : (tpl.petSvg || tpl.bubbleSvg);
  return instantiateSvg(raw);
}

