/**
 * Configuration & Custom Media Storage.
 * Uses localStorage for synchronous config and IndexedDB for uploaded binary/dataURL images.
 */

const STORAGE_KEY = 'agy_custom_theme_config_v1';
const DB_NAME = 'agy_custom_theme_media_v1';
const STORE_NAME = 'assets';
const DEFAULT_CONFIG = {
  enabled: true,
  lang: 'vi',
  wallpaperId: 'thunder-samurai',
  wallpaperFit: 'cover',
  dimming: 16,
  blur: 0,
  glassOpacity: 36,
  accentColor: '#f5c451',
  atmosphereId: 'thunder-rain',
  atmosphereIntensity: 65,
  bubbleId: 'loi-kiem',
  bubbleMascotEnabled: true,
  inputId: 'loi-anh-kim',
  pet: {
    enabled: true,
    id: 'loi-kiem',
    size: 88,
    opacity: 96,
    mode: 'float', // 'float' | 'roam' | 'follow'
    pos: { xPct: 22, yPct: 12 },
    showSpeechOnClick: true
  },
  stickers: {
    enabled: true,
    items: [
      { id: 'bua-loi-an', slot: 'input-top-right', size: 54, glow: true, opacity: 96, pos: { xPct: 82, yPct: 72 } },
      { id: 'trang-sao', slot: 'greeting-badge', size: 46, glow: true, opacity: 92, pos: { xPct: 68, yPct: 46 } }
    ]
  },
  customSelectors: {
    appShell: '',
    sidebar: '',
    mainCanvas: '',
    chatBubble: '',
    chatInput: '',
    settingsNavList: '',
    settingsContent: ''
  },
  hiddenWallpapers: [],
  hiddenStickers: [],
  hiddenPets: [],
  customBundles: []
};

function deepClone(obj) {
  return JSON.parse(JSON.stringify(obj));
}

function mergeDeep(base, patch) {
  const out = deepClone(base);
  if (!patch || typeof patch !== 'object') return out;
  for (const [k, v] of Object.entries(patch)) {
    if (Array.isArray(v)) {
      out[k] = deepClone(v);
    } else if (v && typeof v === 'object' && !Array.isArray(out[k]) && typeof out[k] === 'object') {
      out[k] = mergeDeep(out[k], v);
    } else if (v !== undefined) {
      out[k] = v;
    }
  }
  return out;
}

/**
 * Send a persistence message to the host sync process (inject.mjs) through the
 * CDP `Runtime.addBinding` bridge, so config/media survive app restarts even when
 * the Electron page's localStorage/IndexedDB origin changes or is not persisted.
 */
function persistToHost(message) {
  try {
    const fn = typeof window !== 'undefined' ? window.__agyCtPersist : null;
    if (typeof fn === 'function') fn(JSON.stringify(message));
  } catch {
    // Host bridge unavailable (preview.html / manual DevTools run)
  }
}

function getBootData() {
  try {
    const boot = typeof window !== 'undefined' ? window.__AGY_CT_BOOT__ : null;
    return boot && typeof boot === 'object' ? boot : null;
  } catch {
    return null;
  }
}

function readLocalConfig() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}
function loadConfig() {
  const local = readLocalConfig();
  const bootCfg = getBootData()?.config;
  const boot = bootCfg && typeof bootCfg === 'object' ? bootCfg : null;

  let chosen = local;
  if (boot && (!local || Number(boot.__savedAt || 0) >= Number(local.__savedAt || 0))) {
    chosen = boot;
  }
  if (!chosen) return deepClone(DEFAULT_CONFIG);

  const cfg = mergeDeep(DEFAULT_CONFIG, chosen);
  if (chosen === boot) {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(cfg));
    } catch {
      // Ignore storage quota errors in restricted sandboxes
    }
  }
  return cfg;
}
function saveConfig(cfg) {
  cfg.__savedAt = Date.now();
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(cfg));
  } catch {
    // Ignore storage quota errors in restricted sandboxes
  }
  persistToHost({ type: 'config', data: cfg });
}

/** Push current config to host only if host has no saved config yet (initial migration). */
function syncConfigToHost(cfg) {
  persistToHost({ type: 'config-init', data: cfg });
}

/** Reset look & feel to defaults while keeping permanently deleted items deleted. */
function resetConfig(current = null) {
  const fresh = deepClone(DEFAULT_CONFIG);
  if (current) {
    fresh.hiddenWallpapers = [...(current.hiddenWallpapers || [])];
    fresh.hiddenStickers = [...(current.hiddenStickers || [])];
    fresh.hiddenPets = [...(current.hiddenPets || [])];
    fresh.customBundles = deepClone(current.customBundles || []);
    fresh.customSelectors = { ...fresh.customSelectors, ...(current.customSelectors || {}) };
    const hiddenStickers = new Set(fresh.hiddenStickers);
    fresh.stickers.items = fresh.stickers.items.filter((it) => !hiddenStickers.has(it.id));
    if (fresh.hiddenPets.includes(fresh.pet.id)) fresh.pet.enabled = false;
    if (fresh.hiddenWallpapers.includes(fresh.wallpaperId)) fresh.wallpaperId = 'none';
  }
  saveConfig(fresh);
  return fresh;
}
function mergeConfig(current, patch) {
  return mergeDeep(current, patch);
}

// IndexedDB helper for large custom user images (wallpaper / custom pet / custom sticker)
function openMediaDb() {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('IndexedDB unavailable'));
      return;
    }
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}
async function saveCustomMedia(key, dataUrl) {
  persistToHost({ type: 'media', key, dataUrl });
  await writeMediaToDb(key, dataUrl);
}

async function writeMediaToDb(key, dataUrl) {
  try {
    const db = await openMediaDb();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).put(dataUrl, key);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
    db.close();
  } catch {
    // Fallback to session memory handled by caller
  }
}

async function deleteMediaFromDb(key) {
  try {
    const db = await openMediaDb();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).delete(key);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
    db.close();
  } catch {
    // Ignore when IndexedDB unavailable
  }
}
async function deleteCustomMedia(key) {
  persistToHost({ type: 'media', key, dataUrl: null });
  await deleteMediaFromDb(key);
}
async function clearAllCustomMedia() {
  persistToHost({ type: 'media-clear' });
  try {
    const db = await openMediaDb();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).clear();
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
    db.close();
  } catch {
    // Ignore when IndexedDB unavailable
  }
}
async function loadCustomMediaMap() {
  const keys = ['wallpaper', 'pet', 'sticker'];
  const result = {};
  try {
    const db = await openMediaDb();
    await Promise.all(
      keys.map(
        (key) =>
          new Promise((resolve) => {
            const tx = db.transaction(STORE_NAME, 'readonly');
            const req = tx.objectStore(STORE_NAME).get(key);
            req.onsuccess = () => {
              if (req.result) result[key] = req.result;
              resolve();
            };
            req.onerror = () => resolve();
          })
      )
    );
    db.close();
  } catch {
    // Ignore when IndexedDB unavailable
  }

  // Merge media persisted on disk by the host sync process (survives origin/profile changes)
  const boot = getBootData();
  if (boot) {
    const hasHostConfig = Boolean(boot.config && typeof boot.config === 'object');
    const bootMedia = boot.media && typeof boot.media === 'object' ? boot.media : {};
    for (const key of keys) {
      const fromDisk = typeof bootMedia[key] === 'string' ? bootMedia[key] : '';
      if (fromDisk && (!result[key] || (hasHostConfig && result[key] !== fromDisk))) {
        result[key] = fromDisk;
        writeMediaToDb(key, fromDisk);
      } else if (result[key] && !fromDisk) {
        if (hasHostConfig) {
          // Host disk state is authoritative once initialized: purge stale deleted media from IndexedDB
          delete result[key];
          deleteMediaFromDb(key);
        } else {
          persistToHost({ type: 'media', key, dataUrl: result[key] });
        }
      }
    }
  }
  return result;
}

  // ===== core/styles.js =====
const STYLE_ID = 'agy-ct-styles';

function resolveActiveWallpaperUrl(config, customMedia = {}) {
  if (!config?.enabled) return '';
  if (config.wallpaperId === 'custom') {
    return customMedia.wallpaper || '';
  }
  const wp = WALLPAPERS.find((w) => w.id === config.wallpaperId);
  return resolveWallpaperUrl(wp, customMedia);
}
function buildStylesheet(config, customMedia = {}) {
  const bubble = BUBBLE_PRESETS.find((b) => b.id === config.bubbleId) || BUBBLE_PRESETS[0];
  const inputPreset = INPUT_PRESETS.find((i) => i.id === config.inputId) || INPUT_PRESETS[0];
  const wallpaperUrl = resolveActiveWallpaperUrl(config, customMedia);

  const hasWallpaper = Boolean(config.enabled && wallpaperUrl);
  const dimAlpha = Math.max(0, Math.min(0.95, (config.dimming ?? 48) / 100));
  const glassAlpha = Math.max(0.18, Math.min(0.95, (config.glassOpacity ?? 64) / 100));
  const blurPx = Math.max(0, Math.min(24, Number(config.blur ?? 0)));
  const accent = config.accentColor || '#f5c451';

  const scrollCapCss = bubble.scrollCaps
    ? `
      .agy-ct-bubble-styled::before,
      .agy-ct-bubble-styled::after {
        content: '';
        position: absolute;
        top: -3px;
        bottom: -3px;
        width: 8px;
        border-radius: 4px;
        background: linear-gradient(180deg, #b88a44, #5c3a14 50%, #b88a44);
        border: 1px solid #2e1b08;
        box-shadow: 0 2px 6px rgba(0,0,0,0.45);
        pointer-events: none;
      }
      .agy-ct-bubble-styled::before { left: -5px; }
      .agy-ct-bubble-styled::after { right: -5px; }
    `
    : '';

  const cyberCornerCss = bubble.cyberCorners
    ? `
      .agy-ct-bubble-styled::before {
        content: '';
        position: absolute;
        inset: -1px;
        border-radius: inherit;
        background: linear-gradient(135deg, rgba(56,189,248,0.45), transparent 35%, transparent 65%, rgba(16,185,129,0.45));
        -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
        -webkit-mask-composite: xor;
        mask-composite: exclude;
        padding: 1.5px;
        pointer-events: none;
      }
    `
    : '';

  return `
    :root {
      --agy-ct-accent: ${accent};
      --agy-ct-glass-alpha: ${glassAlpha};
      --agy-ct-dim-alpha: ${dimAlpha};
      --agy-ct-blur: ${blurPx}px;
    }

    /* ===== Background Wallpaper & Ambient Layers ===== */
    html.agy-ct-active,
    html:has(body.agy-ct-active),
    body.agy-ct-active {
      background: transparent !important;
      background-color: transparent !important;
    }

    body.agy-ct-active {
      position: relative;
      z-index: 0;
    }

    #agy-ct-bg-root {
      position: fixed;
      inset: 0;
      z-index: -1;
      pointer-events: none;
      overflow: hidden;
      display: ${hasWallpaper ? 'block' : 'none'};
    }

    #agy-ct-bg-image {
      position: absolute;
      inset: ${blurPx > 0 ? '-18px' : '0'};
      background-size: ${config.wallpaperFit === 'contain' ? 'contain' : 'cover'};
      background-position: center center;
      background-repeat: no-repeat;
      filter: ${blurPx > 0 ? 'blur(var(--agy-ct-blur))' : 'none'};
      transform: ${blurPx > 0 ? 'scale(1.03)' : 'none'};
      transition: filter 0.2s ease;
    }

    #agy-ct-bg-dim {
      position: absolute;
      inset: 0;
      background: radial-gradient(circle at 55% 42%, rgba(8, 10, 14, calc(var(--agy-ct-dim-alpha) * 0.65)), rgba(6, 7, 10, calc(var(--agy-ct-dim-alpha) * 1.05)));
      transition: background 0.15s ease;
    }

    #agy-ct-ambient-canvas {
      position: fixed;
      inset: 0;
      width: 100vw;
      height: 100vh;
      z-index: -1;
      pointer-events: none;
      display: ${config.enabled && config.atmosphereId !== 'none' ? 'block' : 'none'};
    }

    /* Allow wallpaper to shine subtly through native translucent panels when enabled */
    ${
      hasWallpaper
        ? `
      body.agy-ct-active .agy-ct-surface-shell {
        background: transparent !important;
        background-color: transparent !important;
        background-image: none !important;
      }
      body.agy-ct-active .agy-ct-surface-sidebar {
        background: rgba(10, 14, 22, ${Math.min(0.46, glassAlpha * 0.42).toFixed(2)}) !important;
        background-color: rgba(10, 14, 22, ${Math.min(0.46, glassAlpha * 0.42).toFixed(2)}) !important;
        background-image: none !important;
        backdrop-filter: blur(2px) saturate(118%);
        -webkit-backdrop-filter: blur(2px) saturate(118%);
        border-color: rgba(255, 255, 255, 0.12) !important;
      }
      body.agy-ct-active .agy-ct-surface-sidebar-inner {
        background: transparent !important;
        background-color: transparent !important;
        background-image: none !important;
        box-shadow: none !important;
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
      }
      body.agy-ct-active .agy-ct-surface-canvas {
        background: transparent !important;
        background-color: transparent !important;
        background-image: none !important;
        box-shadow: none !important;
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
      }
      body.agy-ct-active .agy-ct-surface-topbar {
        background: rgba(10, 14, 22, ${Math.min(0.42, glassAlpha * 0.34).toFixed(2)}) !important;
        background-color: rgba(10, 14, 22, ${Math.min(0.42, glassAlpha * 0.34).toFixed(2)}) !important;
        background-image: none !important;
        backdrop-filter: blur(3px) saturate(115%);
        -webkit-backdrop-filter: blur(3px) saturate(115%);
        border-color: rgba(255, 255, 255, 0.08) !important;
      }
    `
        : ''
    }

    /* ===== Styled Chat Bubbles ===== */
    ${
      config.enabled && config.bubbleId !== 'none'
        ? `
      .agy-ct-bubble-styled {
        position: relative !important;
        background: ${bubble.bg} !important;
        border: ${bubble.border} !important;
        color: ${bubble.text} !important;
        box-shadow: ${bubble.shadow} !important;
        border-radius: ${bubble.radius} !important;
        overflow: visible !important;
        transition: transform 0.2s ease, box-shadow 0.2s ease;
      }
      .agy-ct-bubble-styled * {
        color: inherit;
      }
      .agy-ct-bubble-styled pre {
        background: rgba(10, 12, 16, 0.72) !important;
        border: 1px solid rgba(255, 255, 255, 0.08) !important;
        border-radius: 8px !important;
      }
      .agy-ct-bubble-styled pre,
      .agy-ct-bubble-styled code {
        color: #e4e4e7 !important;
      }
      ${scrollCapCss}
      ${cyberCornerCss}

      .agy-ct-bubble-mascot {
        position: absolute;
        pointer-events: none;
        z-index: 4;
        filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.55));
      }
      .agy-ct-bubble-mascot--right-top {
        top: -34px;
        right: 14px;
        width: 58px;
        height: 46px;
      }
      .agy-ct-bubble-mascot--top-center {
        top: -22px;
        left: 50%;
        transform: translateX(-50%);
        width: 84px;
        height: 36px;
      }

      /* ===== Styled Chat Input Box ===== */
      ${
        config.inputId !== 'none'
          ? `
      .agy-ct-input-styled {
        position: relative !important;
        background: ${inputPreset.bg} !important;
        border: ${inputPreset.border} !important;
        box-shadow: ${inputPreset.shadow} !important;
        border-radius: ${inputPreset.radius} !important;
        backdrop-filter: blur(${inputPreset.blur}) !important;
        -webkit-backdrop-filter: blur(${inputPreset.blur}) !important;
        transition: border-color 0.2s ease, box-shadow 0.2s ease !important;
      }
      .agy-ct-input-styled:focus-within {
        border-color: ${inputPreset.focusBorder} !important;
      }
      `
          : ''
      }
    `
        : ''
    }

    /* ===== SVG Character Animations ===== */
    .agy-ct-svg-art {
      width: 100%;
      height: 100%;
      display: block;
      overflow: visible;
    }
    @keyframes agyCtBob {
      0%, 100% { transform: translateY(0px); }
      50% { transform: translateY(-2.5px); }
    }
    @keyframes agyCtFloat {
      0%, 100% { transform: translateY(0px) rotate(-1deg); }
      50% { transform: translateY(-6px) rotate(1.5deg); }
    }
    @keyframes agyCtBlink {
      0%, 92%, 100% { transform: scaleY(1); }
      95% { transform: scaleY(0.1); }
    }
    @keyframes agyCtWag {
      0%, 100% { transform: rotate(-4deg); }
      50% { transform: rotate(6deg); }
    }
    @keyframes agyCtTwinkle {
      0%, 100% { opacity: 0.45; transform: scale(0.9); }
      50% { opacity: 1; transform: scale(1.12); }
    }
    @keyframes agyCtSpark {
      0%, 100% { opacity: 0.6; filter: drop-shadow(0 0 2px #fde047); }
      45% { opacity: 1; filter: drop-shadow(0 0 6px #fef08a); }
      52% { opacity: 0.35; }
      60% { opacity: 1; }
    }
    @keyframes agyCtSpin {
      from { transform: rotate(0deg); }
      to { transform: rotate(360deg); }
    }
    .agy-ct-anim-bob { animation: agyCtBob 3.2s ease-in-out infinite; }
    .agy-ct-anim-float { animation: agyCtFloat 4.2s ease-in-out infinite; }
    .agy-ct-anim-blink { animation: agyCtBlink 4.6s ease-in-out infinite; }
    .agy-ct-anim-wag { animation: agyCtWag 2.4s ease-in-out infinite; }
    .agy-ct-anim-twinkle { animation: agyCtTwinkle 2.6s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
    .agy-ct-anim-spark { animation: agyCtSpark 1.8s linear infinite; }
    .agy-ct-anim-spin { animation: agyCtSpin 16s linear infinite; }

    /* ===== Floating Pet Stage ===== */
    #agy-ct-pet-stage {
      position: fixed;
      z-index: 45;
      cursor: grab;
      user-select: none;
      touch-action: none;
      transition: filter 0.2s ease;
    }
    #agy-ct-pet-stage:active { cursor: grabbing; }
    #agy-ct-pet-stage:hover .agy-ct-pet-body { transform: scale(1.07); }
    .agy-ct-pet-body {
      width: 100%;
      height: 100%;
      transition: transform 0.2s ease;
    }
    .agy-ct-pet-speech {
      position: absolute;
      bottom: calc(100% + 8px);
      left: 50%;
      transform: translateX(-50%) translateY(4px);
      background: rgba(20, 20, 24, 0.94);
      color: #f8fafc;
      border: 1px solid var(--agy-ct-accent);
      border-radius: 10px;
      padding: 6px 10px;
      font-size: 12px;
      line-height: 1.35;
      white-space: nowrap;
      box-shadow: 0 8px 20px rgba(0, 0, 0, 0.5);
      pointer-events: none;
      opacity: 0;
      transition: opacity 0.22s ease, transform 0.22s ease;
    }
    .agy-ct-pet-speech.is-visible {
      opacity: 1;
      transform: translateX(-50%) translateY(0);
    }
    .agy-ct-pet-burst {
      position: fixed;
      pointer-events: none;
      z-index: 960;
      font-size: 14px;
      animation: agyCtBurstUp 0.95s ease-out forwards;
    }
    @keyframes agyCtBurstUp {
      0% { opacity: 1; transform: translate(0, 0) scale(0.7); }
      100% { opacity: 0; transform: translate(var(--dx, 0px), var(--dy, -36px)) scale(1.2); }
    }

    /* ===== Decorative Stickers ===== */
    .agy-ct-sticker-node {
      position: fixed;
      z-index: 40;
      cursor: grab;
      user-select: none;
      touch-action: none;
      transition: transform 0.2s ease, opacity 0.2s ease;
    }
    .agy-ct-sticker-node:hover {
      transform: scale(1.1) rotate(3deg);
    }
    .agy-ct-sticker-node.has-glow {
      filter: drop-shadow(0 0 10px rgba(255, 255, 255, 0.24));
    }

    /* ===== Settings Nav Injection & Panel UI ===== */
    .agy-ct-nav-fallback {
      display: flex;
      align-items: center;
      gap: 10px;
      width: 100%;
      padding: 8px 12px;
      border-radius: 8px;
      border: none;
      background: transparent;
      color: rgba(255, 255, 255, 0.72);
      font-size: 13.5px;
      font-weight: 500;
      cursor: pointer;
      text-align: left;
      transition: background 0.15s ease, color 0.15s ease;
    }
    .agy-ct-nav-fallback:hover {
      background: rgba(255, 255, 255, 0.06);
      color: #fff;
    }
    .agy-ct-nav-item.is-active {
      background: rgba(255, 255, 255, 0.11) !important;
      color: #ffffff !important;
    }
    [data-agy-ct-custom-active="true"] > :not([data-agy-ct-injected="true"]) {
      background: transparent !important;
      color: rgba(255, 255, 255, 0.72) !important;
    }

    #agy-ct-settings-panel {
      display: none;
      flex-direction: column;
      gap: 24px;
      padding: 20px 26px 42px;
      color: #e4e4e7;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, Roboto, sans-serif;
      box-sizing: border-box;
      width: 100%;
      max-width: 780px;
    }
    #agy-ct-settings-panel *, #agy-ct-settings-panel *::before, #agy-ct-settings-panel *::after {
      box-sizing: border-box;
    }
    #agy-ct-settings-panel.is-open {
      display: flex;
    }
    .agy-ct-hidden-native {
      display: none !important;
    }

    .agy-ct-header-bar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 12px;
      padding-bottom: 14px;
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    }
    .agy-ct-title-wrap h2 {
      margin: 0;
      font-size: 18px;
      font-weight: 600;
      color: #ffffff;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .agy-ct-title-wrap p {
      margin: 4px 0 0;
      font-size: 12.5px;
      color: #a1a1aa;
    }
    .agy-ct-actions-row {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: wrap;
    }

    .agy-ct-btn {
      background: rgba(255, 255, 255, 0.07);
      color: #e4e4e7;
      border: 1px solid rgba(255, 255, 255, 0.12);
      border-radius: 8px;
      padding: 6px 11px;
      font-size: 12px;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.15s ease;
    }
    .agy-ct-btn:hover {
      background: rgba(255, 255, 255, 0.13);
      border-color: rgba(255, 255, 255, 0.24);
    }
    .agy-ct-btn-accent {
      background: color-mix(in srgb, var(--agy-ct-accent) 20%, transparent);
      border-color: color-mix(in srgb, var(--agy-ct-accent) 60%, transparent);
      color: #fff;
    }
    .agy-ct-btn-danger {
      background: rgba(185, 28, 28, 0.85);
      border-color: rgba(248, 113, 113, 0.55);
      color: #fff;
    }
    .agy-ct-btn-danger:hover {
      background: rgba(220, 38, 38, 0.95);
      border-color: rgba(252, 165, 165, 0.8);
    }

    /* Custom Bundles & Modal Dialogs */
    .agy-ct-bundle-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
    }
    .agy-ct-bundle-actions {
      display: flex;
      align-items: center;
      gap: 6px;
      margin-top: 6px;
      padding-top: 6px;
      border-top: 1px solid rgba(255, 255, 255, 0.07);
    }
    .agy-ct-mini-btn {
      background: rgba(255, 255, 255, 0.06);
      color: #e4e4e7;
      border: 1px solid rgba(255, 255, 255, 0.12);
      border-radius: 7px;
      padding: 4px 8px;
      font-size: 11px;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.14s ease;
    }
    .agy-ct-mini-btn:hover {
      background: rgba(255, 255, 255, 0.14);
      border-color: rgba(255, 255, 255, 0.28);
    }
    .agy-ct-mini-btn--danger {
      color: #fca5a5;
    }
    .agy-ct-mini-btn--danger:hover {
      background: rgba(185, 28, 28, 0.85);
      border-color: rgba(248, 113, 113, 0.65);
      color: #fff;
    }
    .agy-ct-empty-hint {
      font-size: 12px;
      color: #a1a1aa;
      background: rgba(255, 255, 255, 0.025);
      border: 1px dashed rgba(255, 255, 255, 0.12);
      border-radius: 10px;
      padding: 10px 12px;
      line-height: 1.45;
    }
    #agy-ct-modal-overlay {
      position: fixed;
      inset: 0;
      z-index: 10030;
      background: rgba(5, 6, 10, 0.72);
      backdrop-filter: blur(6px);
      -webkit-backdrop-filter: blur(6px);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 20px;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, Roboto, sans-serif;
    }
    .agy-ct-modal-card {
      width: min(480px, 94vw);
      max-height: 86vh;
      overflow: auto;
      background: #18181b;
      color: #f4f4f5;
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 14px;
      padding: 18px 20px;
      box-shadow: 0 24px 60px rgba(0, 0, 0, 0.78);
      display: flex;
      flex-direction: column;
      gap: 14px;
    }
    .agy-ct-modal-head h4 {
      margin: 0;
      font-size: 15.5px;
      font-weight: 600;
      color: #ffffff;
    }
    .agy-ct-modal-body {
      font-size: 13px;
      color: #d4d4d8;
      line-height: 1.5;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }
    .agy-ct-modal-note {
      font-size: 12px;
      color: #a1a1aa;
    }
    .agy-ct-modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 8px;
      flex-wrap: wrap;
      padding-top: 6px;
    }
    .agy-ct-form-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 10px;
    }
    @media (max-width: 520px) {
      .agy-ct-form-grid { grid-template-columns: 1fr; }
    }
    .agy-ct-field {
      display: flex;
      flex-direction: column;
      gap: 4px;
      font-size: 12px;
      color: #d4d4d8;
    }
    .agy-ct-field--full {
      grid-column: 1 / -1;
    }
    .agy-ct-input {
      background: #101116;
      color: #f4f4f5;
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 7px;
      padding: 6px 9px;
      font-size: 12.5px;
      width: 100%;
    }

    .agy-ct-section {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }
    .agy-ct-section-head h3 {
      margin: 0;
      font-size: 14.5px;
      font-weight: 600;
      color: #f4f4f5;
    }
    .agy-ct-section-head p {
      margin: 3px 0 0;
      font-size: 12.5px;
      color: #9ca3af;
    }

    .agy-ct-bundle-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(195px, 1fr));
      gap: 10px;
    }
    .agy-ct-bundle-card {
      position: relative;
      display: flex;
      flex-direction: column;
      gap: 6px;
      padding: 12px;
      border-radius: 12px;
      background: rgba(255, 255, 255, 0.035);
      border: 1px solid rgba(255, 255, 255, 0.09);
      cursor: pointer;
      text-align: left;
      color: #f4f4f5;
      transition: all 0.16s ease;
    }
    .agy-ct-bundle-card:hover {
      background: rgba(255, 255, 255, 0.07);
      border-color: rgba(255, 255, 255, 0.22);
      transform: translateY(-1px);
    }
    .agy-ct-bundle-badge {
      align-self: flex-start;
      font-size: 10.5px;
      padding: 2px 7px;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.09);
      color: var(--agy-ct-accent);
      font-weight: 600;
    }
    .agy-ct-bundle-title {
      font-size: 13px;
      font-weight: 600;
    }
    .agy-ct-bundle-sub {
      font-size: 11.5px;
      color: #a1a1aa;
      line-height: 1.35;
    }

    /* Wallpaper grid */
    .agy-ct-wp-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
      gap: 10px;
    }
    .agy-ct-wp-card {
      position: relative;
      border-radius: 11px;
      overflow: hidden;
      background: rgba(255, 255, 255, 0.03);
      border: 1.5px solid rgba(255, 255, 255, 0.1);
      cursor: pointer;
      padding: 0;
      text-align: left;
      transition: all 0.16s ease;
    }
    .agy-ct-wp-card:hover {
      border-color: rgba(255, 255, 255, 0.28);
    }
    .agy-ct-wp-card.is-selected {
      border-color: #ffffff;
      box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.25);
    }
    .agy-ct-wp-thumb {
      height: 82px;
      width: 100%;
      background-size: cover;
      background-position: center;
      background-color: #15161a;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12px;
      color: #71717a;
    }
    .agy-ct-wp-meta {
      padding: 7px 9px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 4px;
      background: rgba(18, 18, 22, 0.92);
      color: #e4e4e7;
      font-size: 11.5px;
      font-weight: 500;
    }

    /* Sliders */
    .agy-ct-controls-box {
      display: flex;
      flex-direction: column;
      gap: 12px;
      padding: 14px;
      border-radius: 12px;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.08);
    }
    .agy-ct-slider-row {
      display: grid;
      grid-template-columns: 1fr auto auto;
      align-items: center;
      gap: 12px;
    }
    .agy-ct-slider-label strong {
      display: block;
      font-size: 13px;
      font-weight: 500;
      color: #f4f4f5;
    }
    .agy-ct-slider-label span {
      display: block;
      font-size: 11.5px;
      color: #9ca3af;
      margin-top: 2px;
    }
    .agy-ct-range {
      width: 140px;
      accent-color: #ffffff;
      cursor: pointer;
    }
    .agy-ct-range-val {
      min-width: 40px;
      text-align: right;
      font-size: 12.5px;
      color: #d4d4d8;
      font-variant-numeric: tabular-nums;
    }

    /* 2-Column Bubble Cards matching Image 1 */
    .agy-ct-bubble-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 12px;
    }
    @media (max-width: 560px) {
      .agy-ct-bubble-grid { grid-template-columns: 1fr; }
    }
    .agy-ct-bubble-card {
      position: relative;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      min-height: 118px;
      padding: 26px 16px 12px;
      border-radius: 12px;
      background: rgba(255, 255, 255, 0.025);
      border: 1.5px solid rgba(255, 255, 255, 0.09);
      cursor: pointer;
      color: #e4e4e7;
      text-align: left;
      transition: all 0.16s ease;
    }
    .agy-ct-bubble-card:hover {
      background: rgba(255, 255, 255, 0.05);
      border-color: rgba(255, 255, 255, 0.25);
    }
    .agy-ct-bubble-card.is-selected {
      border-color: #e4e4e7;
      background: rgba(255, 255, 255, 0.07);
    }
    .agy-ct-preview-bubble-wrap {
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 6px 0 10px;
    }
    .agy-ct-preview-bubble {
      position: relative;
      display: inline-flex;
      align-items: center;
      gap: 6px;
      min-width: 175px;
      padding: 11px 18px;
      font-size: 13.5px;
      font-weight: 500;
    }
    .agy-ct-card-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      font-size: 12.5px;
      color: #d4d4d8;
      margin-top: 4px;
    }
    .agy-ct-check {
      font-size: 13px;
      color: #ffffff;
      font-weight: 700;
    }

    /* Input Box Cards */
    .agy-ct-input-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 10px;
    }
    @media (max-width: 560px) {
      .agy-ct-input-grid { grid-template-columns: 1fr; }
    }
    .agy-ct-input-card {
      display: flex;
      flex-direction: column;
      gap: 8px;
      padding: 12px;
      border-radius: 12px;
      background: rgba(255, 255, 255, 0.025);
      border: 1.5px solid rgba(255, 255, 255, 0.09);
      cursor: pointer;
      color: #e4e4e7;
      text-align: left;
      transition: all 0.16s ease;
    }
    .agy-ct-input-card:hover {
      border-color: rgba(255, 255, 255, 0.25);
    }
    .agy-ct-input-card.is-selected {
      border-color: #ffffff;
      background: rgba(255, 255, 255, 0.07);
    }
    .agy-ct-input-mock {
      padding: 10px 12px;
      font-size: 12px;
      color: rgba(255, 255, 255, 0.55);
    }

    /* Sticker & Pet Grids */
    .agy-ct-asset-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
      gap: 10px;
    }
    .agy-ct-asset-card {
      position: relative;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 6px;
      padding: 10px 8px;
      border-radius: 12px;
      background: rgba(255, 255, 255, 0.03);
      border: 1.5px solid rgba(255, 255, 255, 0.08);
      cursor: pointer;
      color: #e4e4e7;
      transition: all 0.16s ease;
    }
    .agy-ct-asset-card:hover {
      background: rgba(255, 255, 255, 0.07);
      border-color: rgba(255, 255, 255, 0.24);
    }
    .agy-ct-asset-card.is-selected {
      border-color: var(--agy-ct-accent);
      background: color-mix(in srgb, var(--agy-ct-accent) 13%, rgba(255, 255, 255, 0.04));
    }
    .agy-ct-asset-icon {
      width: 56px;
      height: 56px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .agy-ct-asset-icon img {
      max-width: 100%;
      max-height: 100%;
      object-fit: contain;
    }
    .agy-ct-asset-name {
      font-size: 11.5px;
      text-align: center;
      line-height: 1.25;
      color: #e4e4e7;
    }

    .agy-ct-chip-row {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
    }
    .agy-ct-chip {
      padding: 6px 11px;
      border-radius: 999px;
      border: 1px solid rgba(255, 255, 255, 0.12);
      background: rgba(255, 255, 255, 0.04);
      color: #d4d4d8;
      font-size: 12px;
      cursor: pointer;
      transition: all 0.15s ease;
    }
    .agy-ct-chip.is-selected {
      border-color: var(--agy-ct-accent);
      background: color-mix(in srgb, var(--agy-ct-accent) 20%, transparent);
      color: #ffffff;
    }

    .agy-ct-swatch {
      width: 24px;
      height: 24px;
      border-radius: 999px;
      border: 2px solid transparent;
      cursor: pointer;
      transition: transform 0.15s ease;
    }
    .agy-ct-swatch:hover { transform: scale(1.12); }
    .agy-ct-swatch.is-selected { border-color: #ffffff; box-shadow: 0 0 10px rgba(255, 255, 255, 0.4); }

    .agy-ct-select {
      background: #18181b;
      color: #f4f4f5;
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 7px;
      padding: 5px 8px;
      font-size: 12px;
    }

    .agy-ct-switch {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      cursor: pointer;
      font-size: 12.5px;
    }

    /* Visual DOM Picker highlight */
    .agy-ct-picker-hover {
      outline: 2px dashed #facc15 !important;
      outline-offset: 2px !important;
      cursor: crosshair !important;
    }
    .agy-ct-wp-card,
    .agy-ct-asset-card {
      position: relative;
    }
    .agy-ct-card-del {
      position: absolute;
      top: 5px;
      right: 5px;
      z-index: 3;
      width: 20px;
      height: 20px;
      border-radius: 999px;
      border: 1px solid rgba(255, 255, 255, 0.22);
      background: rgba(15, 16, 22, 0.85);
      color: #fca5a5;
      font-size: 11px;
      line-height: 1;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      opacity: 0.78;
      transition: opacity 0.15s ease, background 0.15s ease, transform 0.15s ease;
    }
    .agy-ct-card-del:hover {
      opacity: 1;
      background: rgba(185, 28, 28, 0.9);
      color: #fff;
      transform: scale(1.08);
    }
    #agy-ct-picker-banner {
      position: fixed;
      top: 14px;
      left: 50%;
      transform: translateX(-50%);
      z-index: 99999;
      background: #18181b;
      color: #fef08a;
      border: 1.5px solid #facc15;
      border-radius: 10px;
      padding: 8px 14px;
      font-size: 12.5px;
      display: flex;
      align-items: center;
      gap: 10px;
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.65);
    }

    /* Quick 1-click Floating Launcher Pill */
    #agy-ct-launcher {
      position: fixed;
      top: 46px;
      right: 16px;
      z-index: 9980;
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 6px 12px;
      border-radius: 999px;
      background: rgba(20, 22, 28, 0.78);
      color: #f4f4f5;
      border: 1px solid color-mix(in srgb, var(--agy-ct-accent) 45%, rgba(255, 255, 255, 0.16));
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
      font-size: 12px;
      font-weight: 500;
      cursor: pointer;
      box-shadow: 0 6px 20px rgba(0, 0, 0, 0.45);
      transition: transform 0.15s ease, border-color 0.15s ease, background 0.15s ease;
    }
    #agy-ct-launcher:hover {
      transform: translateY(-1px);
      background: rgba(28, 30, 38, 0.9);
      border-color: var(--agy-ct-accent);
    }
  `;
}
function applyStylesheet(config, customMedia = {}) {
  let el = document.getElementById(STYLE_ID);
  if (!el) {
    el = document.createElement('style');
    el.id = STYLE_ID;
    document.head.appendChild(el);
  }
  el.textContent = buildStylesheet(config, customMedia);

  const wallpaperUrl = resolveActiveWallpaperUrl(config, customMedia);
  const imgLayer = document.getElementById('agy-ct-bg-image');
  if (imgLayer && imgLayer._agyWpUrl !== wallpaperUrl) {
    imgLayer._agyWpUrl = wallpaperUrl;
    imgLayer.style.backgroundImage = wallpaperUrl ? `url("${wallpaperUrl.replace(/"/g, '\\"')}")` : 'none';
  }

  if (config.enabled) {
    document.documentElement.classList.add('agy-ct-active');
    document.body.classList.add('agy-ct-active');
  } else {
    document.documentElement.classList.remove('agy-ct-active');
    document.body.classList.remove('agy-ct-active');
  }
}
function ensureBackgroundLayers() {
  let canvas = document.getElementById('agy-ct-ambient-canvas');
  if (!canvas) {
    canvas = document.createElement('canvas');
    canvas.id = 'agy-ct-ambient-canvas';
    document.body.prepend(canvas);
  }
  let root = document.getElementById('agy-ct-bg-root');
  if (!root) {
    root = document.createElement('div');
    root.id = 'agy-ct-bg-root';
    const imgLayer = document.createElement('div');
    imgLayer.id = 'agy-ct-bg-image';
    const dimLayer = document.createElement('div');
    dimLayer.id = 'agy-ct-bg-dim';
    root.appendChild(imgLayer);
    root.appendChild(dimLayer);
    // Keep bg-root directly before ambient-canvas so rain/stars paint on top of wallpaper at z-index: -1
    document.body.prepend(root);
  }
  return { root, canvas };
}
function removeBackgroundLayers() {
  document.getElementById(STYLE_ID)?.remove();
  document.getElementById('agy-ct-bg-root')?.remove();
  document.getElementById('agy-ct-ambient-canvas')?.remove();
  document.getElementById('agy-ct-launcher')?.remove();
  document.getElementById('agy-ct-modal-overlay')?.remove();
  document.documentElement.classList.remove('agy-ct-active');
  document.body.classList.remove('agy-ct-active');
}

  // ===== core/ambient-canvas.js =====
/**
 * Lightweight hardware-friendly Ambient Particle Canvas.
 * Supports: thunder-rain (matches Image 3), rain, stardust, sakura, fireflies, none.
 */
class AmbientCanvasEngine {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.mode = 'none';
    this.intensity = 65;
    this.particles = [];
    this.sparks = [];
    this.rafId = null;
    this.lastTs = 0;
    this.destroyed = false;

    this.onResize = this.resize.bind(this);
    this.onVisibility = () => {
      if (document.hidden) {
        this.stopLoop();
      } else if (this.mode !== 'none' && !this.destroyed) {
        this.startLoop();
      }
    };

    window.addEventListener('resize', this.onResize);
    document.addEventListener('visibilitychange', this.onVisibility);
    this.resize();
  }

  resize() {
    if (!this.canvas) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 1.5);
    this.width = window.innerWidth;
    this.height = window.innerHeight;
    this.canvas.width = Math.floor(this.width * dpr);
    this.canvas.height = Math.floor(this.height * dpr);
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  configure(mode, intensity = 65) {
    const changed = this.mode !== mode || Math.abs(this.intensity - intensity) > 8;
    this.mode = mode || 'none';
    this.intensity = Math.max(10, Math.min(100, Number(intensity) || 65));

    if (this.mode === 'none') {
      this.stopLoop();
      this.clear();
      return;
    }

    if (changed || this.particles.length === 0) {
      this.seedParticles();
    }
    if (!document.hidden && !this.rafId) {
      this.startLoop();
    }
  }

  seedParticles() {
    const factor = this.intensity / 100;
    const w = this.width || window.innerWidth;
    const h = this.height || window.innerHeight;
    this.particles = [];
    this.sparks = [];

    let count = 45;
    if (this.mode === 'thunder-rain' || this.mode === 'rain') {
      count = Math.round(55 + factor * 85);
    } else if (this.mode === 'stardust') {
      count = Math.round(35 + factor * 65);
    } else if (this.mode === 'sakura') {
      count = Math.round(18 + factor * 30);
    } else if (this.mode === 'fireflies') {
      count = Math.round(22 + factor * 36);
    }

    for (let i = 0; i < count; i++) {
      this.particles.push(this.createParticle(w, h, true));
    }
  }

  createParticle(w, h, randomY = false) {
    const x = Math.random() * (w + 120) - 60;
    const y = randomY ? Math.random() * h : -20;

    if (this.mode === 'thunder-rain' || this.mode === 'rain') {
      return {
        x,
        y,
        len: 12 + Math.random() * 18,
        vx: -1.4 - Math.random() * 1.2,
        vy: 8 + Math.random() * 7,
        alpha: 0.14 + Math.random() * 0.24
      };
    }

    if (this.mode === 'sakura') {
      return {
        x,
        y,
        size: 5 + Math.random() * 6,
        vx: 0.4 + Math.random() * 0.9,
        vy: 0.8 + Math.random() * 1.1,
        angle: Math.random() * Math.PI * 2,
        spin: (Math.random() - 0.5) * 0.04,
        swayPhase: Math.random() * Math.PI * 2,
        alpha: 0.45 + Math.random() * 0.4
      };
    }

    if (this.mode === 'fireflies') {
      return {
        x: Math.random() * w,
        y: Math.random() * h,
        r: 1.5 + Math.random() * 2.4,
        vx: (Math.random() - 0.5) * 0.5,
        vy: (Math.random() - 0.5) * 0.45,
        phase: Math.random() * Math.PI * 2,
        hue: Math.random() > 0.28 ? '#34d399' : '#fde047'
      };
    }

    // stardust
    return {
      x: Math.random() * w,
      y: randomY ? Math.random() * h : h + 10,
      r: 0.8 + Math.random() * 1.9,
      vx: (Math.random() - 0.5) * 0.25,
      vy: -0.25 - Math.random() * 0.45,
      phase: Math.random() * Math.PI * 2,
      color: Math.random() > 0.35 ? '#fef3c7' : '#93c5fd'
    };
  }

  maybeSpawnLightningSpark(w, h) {
    if (this.mode !== 'thunder-rain') return;
    if (this.sparks.length < 4 && Math.random() < 0.028 * (this.intensity / 65)) {
      const startX = w * (0.25 + Math.random() * 0.55);
      const startY = h * (0.15 + Math.random() * 0.65);
      const pts = [{ x: startX, y: startY }];
      let cx = startX;
      let cy = startY;
      const segs = 4 + Math.floor(Math.random() * 4);
      for (let i = 0; i < segs; i++) {
        cx += (Math.random() - 0.5) * 42;
        cy += (Math.random() - 0.35) * 40;
        pts.push({ x: cx, y: cy });
      }
      this.sparks.push({ pts, life: 1, decay: 0.045 + Math.random() * 0.03 });
    }
  }

  startLoop() {
    this.stopLoop();
    const tick = (ts) => {
      if (this.destroyed || this.mode === 'none') return;
      if (ts - this.lastTs >= 24) {
        this.lastTs = ts;
        this.drawFrame(ts);
      }
      this.rafId = requestAnimationFrame(tick);
    };
    this.rafId = requestAnimationFrame(tick);
  }

  stopLoop() {
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
  }

  clear() {
    if (!this.ctx) return;
    this.ctx.clearRect(0, 0, this.width || 0, this.height || 0);
  }

  drawFrame(ts) {
    const ctx = this.ctx;
    const w = this.width;
    const h = this.height;
    ctx.clearRect(0, 0, w, h);

    if (this.mode === 'thunder-rain' || this.mode === 'rain') {
      ctx.lineCap = 'round';
      ctx.lineWidth = 1;
      for (const p of this.particles) {
        ctx.strokeStyle =
          this.mode === 'thunder-rain'
            ? `rgba(210, 224, 245, ${p.alpha})`
            : `rgba(190, 215, 255, ${p.alpha})`;
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x + p.vx * 1.4, p.y + p.len);
        ctx.stroke();

        p.x += p.vx;
        p.y += p.vy;
        if (p.y > h + 20 || p.x < -80) {
          Object.assign(p, this.createParticle(w, h, false));
        }
      }

      if (this.mode === 'thunder-rain') {
        this.maybeSpawnLightningSpark(w, h);
        for (let i = this.sparks.length - 1; i >= 0; i--) {
          const sp = this.sparks[i];
          ctx.save();
          ctx.strokeStyle = `rgba(253, 224, 71, ${sp.life * 0.85})`;
          ctx.shadowColor = '#facc15';
          ctx.shadowBlur = 10;
          ctx.lineWidth = 1.6;
          ctx.beginPath();
          sp.pts.forEach((pt, idx) => {
            if (idx === 0) ctx.moveTo(pt.x, pt.y);
            else ctx.lineTo(pt.x, pt.y);
          });
          ctx.stroke();
          ctx.restore();
          sp.life -= sp.decay;
          if (sp.life <= 0) this.sparks.splice(i, 1);
        }
      }
      return;
    }

    if (this.mode === 'sakura') {
      for (const p of this.particles) {
        p.swayPhase += 0.03;
        p.x += p.vx + Math.sin(p.swayPhase) * 0.65;
        p.y += p.vy;
        p.angle += p.spin;

        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.angle);
        ctx.fillStyle = `rgba(249, 168, 212, ${p.alpha})`;
        ctx.beginPath();
        ctx.ellipse(0, 0, p.size, p.size * 0.55, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();

        if (p.y > h + 20 || p.x > w + 40) {
          Object.assign(p, this.createParticle(w, h, false));
        }
      }
      return;
    }

    if (this.mode === 'fireflies') {
      for (const p of this.particles) {
        p.x += p.vx + Math.sin(ts * 0.001 + p.phase) * 0.25;
        p.y += p.vy + Math.cos(ts * 0.0012 + p.phase) * 0.2;
        if (p.x < 0) p.x = w;
        if (p.x > w) p.x = 0;
        if (p.y < 0) p.y = h;
        if (p.y > h) p.y = 0;

        const glow = 0.25 + 0.75 * (0.5 + 0.5 * Math.sin(ts * 0.003 + p.phase));
        ctx.save();
        ctx.globalAlpha = glow;
        ctx.fillStyle = p.hue;
        ctx.shadowColor = p.hue;
        ctx.shadowBlur = 12;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
      return;
    }

    // stardust
    for (const p of this.particles) {
      p.x += p.vx;
      p.y += p.vy;
      if (p.y < -10) {
        p.y = h + 10;
        p.x = Math.random() * w;
      }
      const alpha = 0.25 + 0.65 * (0.5 + 0.5 * Math.sin(ts * 0.0025 + p.phase));
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.fillStyle = p.color;
      ctx.shadowColor = p.color;
      ctx.shadowBlur = 6;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  }

  destroy() {
    this.destroyed = true;
    this.stopLoop();
    window.removeEventListener('resize', this.onResize);
    document.removeEventListener('visibilitychange', this.onVisibility);
  }
}

  // ===== core/dom-adapter.js =====
const SETTINGS_SIBLING_LABELS = new Set([
  'general',
  'application',
  'appearance',
  'account',
  'agent',
  'permissions',
  'browser',
  'customizations',
  'editor',
  'terminal',
  'shortcuts',
  'notifications',
  'models',
  'chung',
  'ứng dụng',
  'giao diện',
  'phím tắt',
  'thông báo',
  'mô hình'
]);

const PROTECTED_TAGS = new Set([
  'IMG',
  'SVG',
  'PATH',
  'CANVAS',
  'VIDEO',
  'IFRAME',
  'PRE',
  'CODE',
  'SCRIPT',
  'STYLE',
  'BUTTON',
  'INPUT',
  'TEXTAREA',
  'SELECT'
]);

function parseColorAlpha(value) {
  if (!value || value === 'transparent') return 0;
  const normalized = value.trim().toLowerCase();
  if (normalized === 'transparent' || normalized === 'none') return 0;

  // CSS Color 4 slash alpha syntax: rgb(r g b / a), oklch(l c h / a), color(srgb ... / 50%)
  const slashMatch = normalized.match(/\/\s*([\d.]+)(%?)\s*\)$/);
  if (slashMatch) {
    const raw = Number(slashMatch[1]);
    const alpha = slashMatch[2] === '%' ? raw / 100 : raw;
    return Number.isFinite(alpha) ? alpha : 0;
  }

  // Legacy comma-separated rgba()/hsla()
  const commaAlphaMatch = normalized.match(/^(?:rgba|hsla)\([^,]+,[^,]+,[^,]+,\s*([\d.]+)\s*\)$/);
  if (commaAlphaMatch) {
    const alpha = Number(commaAlphaMatch[1]);
    return Number.isFinite(alpha) ? alpha : 0;
  }

  // Opaque rgb(), hsl(), oklch(), oklab(), lab(), lch(), color() without alpha
  return /^(?:rgb|hsl|oklch|oklab|lab|lch|color)\(/.test(normalized) ? 1 : 0;
}

function isOpaqueColor(value, minAlpha = 0.65) {
  return parseColorAlpha(value) >= minAlpha;
}

function hasDecorativeSurfaceFill(style, minAlpha = 0.55) {
  const hasGradient =
    Boolean(style.backgroundImage) &&
    style.backgroundImage !== 'none' &&
    !style.backgroundImage.includes('url(');
  return isOpaqueColor(style.backgroundColor, minAlpha) || hasGradient;
}

/**
 * Non-destructive DOM adapter.
 * Uses MutationObserver + resilient heuristics + user-overridable customSelectors
 * to hook into Settings navigation, chat bubbles, chat input box, and surface panels
 * without modifying original application code.
 */
class DomAdapter {
  constructor({ getConfig, onCustomNavClick, onNativeNavClick, onConfigPatch }) {
    this.getConfig = getConfig;
    this.onCustomNavClick = onCustomNavClick;
    this.onNativeNavClick = onNativeNavClick;
    this.onConfigPatch = onConfigPatch;

    this.settingsPanelEl = null;
    this.injectedNavBtn = null;
    this.activeContentPane = null;
    this.isCustomSettingsOpen = false;
    this.observer = null;
    this.rafScheduled = false;
    this.pickerCleanup = null;
    this.boundNativeItems = new WeakSet();
  }

  setSettingsPanel(panelEl) {
    this.settingsPanelEl = panelEl;
  }

  start() {
    this.scanAndApply();
    const scheduleScan = () => {
      if (this.rafScheduled) return;
      this.rafScheduled = true;
      requestAnimationFrame(() => {
        this.rafScheduled = false;
        this.scanAndApply();
      });
    };
    this.onWindowResize = scheduleScan;
    window.addEventListener('resize', this.onWindowResize);
    this.observer = new MutationObserver(scheduleScan);
    this.observer.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['class', 'style']
    });
  }

  stop() {
    if (this.onWindowResize) {
      window.removeEventListener('resize', this.onWindowResize);
      this.onWindowResize = null;
    }
    this.observer?.disconnect();
    this.observer = null;
    this.cancelPicker();
    this.cleanupInjectedNodes();
  }

  cleanupInjectedNodes() {
    document.querySelectorAll('[data-agy-ct-custom-active]').forEach((el) => {
      el.removeAttribute('data-agy-ct-custom-active');
    });
    document.querySelectorAll('[data-agy-ct-injected="true"]').forEach((el) => el.remove());
    document.querySelectorAll('.agy-ct-bubble-styled').forEach((el) => {
      el.classList.remove('agy-ct-bubble-styled');
    });
    document.querySelectorAll('.agy-ct-input-styled').forEach((el) => {
      el.classList.remove('agy-ct-input-styled');
    });
    document.querySelectorAll('.agy-ct-hidden-native').forEach((el) => {
      el.classList.remove('agy-ct-hidden-native');
    });
    document
      .querySelectorAll(
        '.agy-ct-surface-shell, .agy-ct-surface-sidebar, .agy-ct-surface-sidebar-inner, .agy-ct-surface-canvas, .agy-ct-surface-topbar'
      )
      .forEach((el) => {
        el.classList.remove(
          'agy-ct-surface-shell',
          'agy-ct-surface-sidebar',
          'agy-ct-surface-sidebar-inner',
          'agy-ct-surface-canvas',
          'agy-ct-surface-topbar'
        );
      });
  }

  scanAndApply() {
    const cfg = this.getConfig();
    this.decorateSurfaces(cfg);
    this.ensureSettingsEntry();

    if (!cfg.enabled) {
      document.querySelectorAll('.agy-ct-bubble-styled').forEach((el) => el.classList.remove('agy-ct-bubble-styled'));
      document.querySelectorAll('.agy-ct-bubble-mascot').forEach((el) => el.remove());
      document.querySelectorAll('.agy-ct-input-styled').forEach((el) => el.classList.remove('agy-ct-input-styled'));
      return;
    }

    this.decorateChatBubbles(cfg);
    this.decorateChatInput(cfg);
  }

  safeQueryAll(selector) {
    if (!selector || typeof selector !== 'string') return [];
    try {
      return Array.from(document.querySelectorAll(selector));
    } catch {
      return [];
    }
  }

  isInsideInjectorUi(el) {
    if (!el) return true;
    return Boolean(
      el.closest('#agy-ct-settings-panel') ||
        el.closest('#agy-ct-fallback-modal') ||
        el.closest('#agy-ct-launcher') ||
        el.closest('#agy-ct-bg-root') ||
        el.closest('#agy-ct-ambient-canvas') ||
        el.closest('#agy-ct-pet-stage') ||
        el.closest('#agy-ct-picker-banner') ||
        el.closest('.agy-ct-sticker-node')
    );
  }

  isProtectedSurfaceEl(el) {
    if (!el || PROTECTED_TAGS.has(el.tagName)) return true;
    const role = el.getAttribute?.('role');
    if (
      role === 'dialog' ||
      role === 'alertdialog' ||
      role === 'menu' ||
      role === 'listbox' ||
      role === 'tooltip' ||
      el.getAttribute?.('aria-modal') === 'true'
    ) {
      return true;
    }
    return Boolean(
      el.closest?.(
        '[role="dialog"], [role="alertdialog"], [role="menu"], [role="listbox"], [role="tooltip"], [aria-modal="true"], [data-radix-popper-content-wrapper]'
      )
    );
  }

  classifyRealAppSurface(el, style, vw, vh, composerBoxes = []) {
    if (this.isInsideInjectorUi(el) || this.isProtectedSurfaceEl(el)) return null;
    if (el.closest?.('.agy-ct-bubble-styled')) return null;
    if (composerBoxes.some((box) => el === box || box.contains(el))) return null;

    const rect = el.getBoundingClientRect();
    if (rect.width < 110 || rect.height < 12) return null;

    const isMajorCanvas = rect.width >= vw * 0.52 && rect.height >= vh * 0.5;
    const isLeftSidebar =
      rect.left <= 24 && rect.width >= 130 && rect.width <= vw * 0.42 && rect.height >= vh * 0.48;
    const isRightPanel =
      rect.right >= vw - 28 &&
      rect.width >= 130 &&
      rect.width <= vw * 0.42 &&
      (rect.height >= vh * 0.45 ||
        (rect.top <= 110 &&
          rect.height >= 140 &&
          Boolean(el.querySelector('a, button, [role="button"], nav'))));
    const isTopBar =
      rect.top <= 16 &&
      rect.height >= 24 &&
      rect.height <= 96 &&
      (rect.width >= vw * 0.3 || (rect.left <= 24 && rect.width >= 120));
    const isComposerDock = composerBoxes.some((box) => {
      if (el === box || !el.contains(box)) return false;
      const boxRect = box.getBoundingClientRect();
      return rect.height <= vh * 0.48 && rect.width > boxRect.width + 48;
    });
    const hasGradient =
      Boolean(style.backgroundImage) &&
      style.backgroundImage !== 'none' &&
      !style.backgroundImage.includes('url(');
    const alpha = parseColorAlpha(style.backgroundColor);
    const hasComposerInside = Boolean(el.querySelector('textarea, [contenteditable="true"]'));
    const hasProseBlock = Boolean(el.querySelector('pre, code, table, blockquote'));
    const isEmptyText = (el.textContent || '').trim() === '';
    const isBottomFadeOrBar =
      !isLeftSidebar &&
      !isRightPanel &&
      !hasProseBlock &&
      rect.bottom >= vh - 340 &&
      rect.height <= 260 &&
      rect.width >= vw * 0.32 &&
      (isComposerDock ||
        hasComposerInside ||
        (hasGradient && isEmptyText) ||
        (alpha >= 0.25 && isEmptyText) ||
        (rect.bottom >= vh - 12 && rect.height <= 64));

    const isEdgeOrLayoutChrome =
      isMajorCanvas || isLeftSidebar || isRightPanel || isTopBar || isComposerDock || isBottomFadeOrBar;

    const zIndex = Number(style.zIndex);
    if (
      !isEdgeOrLayoutChrome &&
      (style.position === 'fixed' || style.position === 'absolute') &&
      Number.isFinite(zIndex) &&
      zIndex >= 40 &&
      rect.width < vw * 0.85 &&
      rect.height < vh * 0.85
    ) {
      return null;
    }

    const minAlpha = isBottomFadeOrBar || isComposerDock ? 0.25 : 0.45;
    const hasFill = hasDecorativeSurfaceFill(style, minAlpha);

    if (!hasFill) {
      const parentWidth = el.parentElement?.getBoundingClientRect?.().width || 0;
      const isStructuralSidebarCol =
        isLeftSidebar &&
        rect.height >= vh * 0.68 &&
        rect.top <= 48 &&
        parentWidth >= vw * 0.72 &&
        !el.parentElement?.closest('.agy-ct-surface-sidebar');
      if (isStructuralSidebarCol) return 'sidebar';

      const isStructuralTopRow =
        rect.top <= 12 &&
        rect.height >= 26 &&
        rect.height <= 88 &&
        rect.width >= vw * 0.68 &&
        !el.parentElement?.closest('.agy-ct-surface-topbar');
      if (isStructuralTopRow) return 'topbar';

      return null;
    }

    if (isMajorCanvas) return 'canvas';
    if (isComposerDock || isBottomFadeOrBar) return 'canvas';
    if (isLeftSidebar || isRightPanel) return 'sidebar';
    if (isTopBar) return 'topbar';
    if (rect.left > 120 && rect.width >= vw * 0.26 && rect.height >= vh * 0.48) return 'canvas';
    if (rect.width >= vw * 0.42 && rect.height >= vh * 0.42) return 'canvas';
    return null;
  }

  decorateSurfaces(cfg) {
    const sel = cfg.customSelectors || {};
    const shell =
      (sel.appShell && this.safeQueryAll(sel.appShell)[0]) ||
      document.querySelector('[data-agy-surface="shell"]');
    const sidebar =
      (sel.sidebar && this.safeQueryAll(sel.sidebar)[0]) ||
      document.querySelector('[data-agy-surface="sidebar"]');
    const canvas =
      (sel.mainCanvas && this.safeQueryAll(sel.mainCanvas)[0]) ||
      document.querySelector('[data-agy-surface="canvas"]');
    const topbar = document.querySelector('[data-agy-surface="topbar"]');

    if (shell) shell.classList.add('agy-ct-surface-shell');
    if (sidebar) sidebar.classList.add('agy-ct-surface-sidebar');
    if (canvas) canvas.classList.add('agy-ct-surface-canvas');
    if (topbar) topbar.classList.add('agy-ct-surface-topbar');

    // Auto-classify real Antigravity Electron surfaces when preview markers are absent
    if (cfg.enabled && !shell && !canvas && document.body) {
      const vw = window.innerWidth;
      const vh = window.innerHeight;
      const composerBoxes = this.findChatInputContainers(cfg);
      const elements = document.body.querySelectorAll('*');
      for (const el of elements) {
        if (
          el.classList.contains('agy-ct-surface-canvas') ||
          el.classList.contains('agy-ct-surface-sidebar') ||
          el.classList.contains('agy-ct-surface-sidebar-inner') ||
          el.classList.contains('agy-ct-surface-topbar')
        ) {
          continue;
        }
        const style = getComputedStyle(el);
        const insideChrome = Boolean(
          el.parentElement?.closest('.agy-ct-surface-sidebar, .agy-ct-surface-topbar')
        );
        if (insideChrome) {
          if (
            !this.isInsideInjectorUi(el) &&
            !this.isProtectedSurfaceEl(el) &&
            !composerBoxes.some((box) => el === box || box.contains(el)) &&
            hasDecorativeSurfaceFill(style, 0.48)
          ) {
            el.classList.add('agy-ct-surface-sidebar-inner');
          }
          continue;
        }
        const surface = this.classifyRealAppSurface(el, style, vw, vh, composerBoxes);
        if (surface === 'canvas') {
          el.classList.add('agy-ct-surface-canvas');
        } else if (surface === 'sidebar') {
          el.classList.add('agy-ct-surface-sidebar');
        } else if (surface === 'topbar' && !el.parentElement?.closest('.agy-ct-surface-topbar')) {
          el.classList.add('agy-ct-surface-topbar');
        }
      }
    }
  }

  /**
   * Locates Settings navigation list by matching sibling labels (General, Appearance, Shortcuts, etc.).
   */
  findSettingsContext() {
    const cfg = this.getConfig();
    if (cfg.customSelectors?.settingsNavList) {
      const customNav = this.safeQueryAll(cfg.customSelectors.settingsNavList)[0];
      if (customNav) {
        const content =
          (cfg.customSelectors.settingsContent && this.safeQueryAll(cfg.customSelectors.settingsContent)[0]) ||
          this.guessSettingsContentPane(customNav);
        return { navList: customNav, contentPane: content };
      }
    }

    const candidates = Array.from(document.querySelectorAll('nav, aside, ul, div')).filter(
      (el) => !this.isInsideInjectorUi(el)
    );

    let bestNav = null;
    let bestScore = 0;

    for (const container of candidates) {
      const clickables = Array.from(
        container.querySelectorAll(
          ':scope > button, :scope > a, :scope > li, :scope > div[role="button"], :scope > div[role="tab"], :scope > div[role="menuitem"], :scope > div[tabindex]'
        )
      );
      if (clickables.length < 3 || clickables.length > 20) continue;

      let matches = 0;
      for (const item of clickables) {
        const text = (item.textContent || '').trim().toLowerCase();
        if (SETTINGS_SIBLING_LABELS.has(text)) matches++;
      }
      if (matches >= 3 && matches > bestScore) {
        bestScore = matches;
        bestNav = container;
      }
    }

    if (!bestNav) return null;
    const contentPane =
      (cfg.customSelectors?.settingsContent && this.safeQueryAll(cfg.customSelectors.settingsContent)[0]) ||
      this.guessSettingsContentPane(bestNav);

    return { navList: bestNav, contentPane };
  }

  guessSettingsContentPane(navList) {
    const explicit = document.querySelector('[data-agy-settings-content]');
    if (explicit) return explicit;
    let parent = navList.parentElement;
    for (let depth = 0; depth < 3 && parent; depth++) {
      const siblings = Array.from(parent.children).filter(
        (ch) => ch !== navList && !ch.contains(navList) && ch.tagName !== 'STYLE'
      );
      const panel = siblings.find((ch) => ch.getBoundingClientRect().width > 240);
      if (panel) return panel;
      parent = parent.parentElement;
    }
    return null;
  }

  ensureSettingsEntry() {
    const ctx = this.findSettingsContext();
    if (!ctx || !ctx.navList) return;

    const { navList, contentPane } = ctx;
    this.activeContentPane = contentPane;

    // Bind native nav clicks to exit Custom theme cleanly
    const navItems = Array.from(navList.children).filter(
      (el) => el.getAttribute('data-agy-ct-injected') !== 'true'
    );
    for (const item of navItems) {
      const label = (item.textContent || '').trim().toLowerCase();
      if (SETTINGS_SIBLING_LABELS.has(label) && !this.boundNativeItems.has(item)) {
        this.boundNativeItems.add(item);
        item.addEventListener('click', () => {
          this.setCustomSettingsOpen(false);
          this.onNativeNavClick?.();
        });
      }
    }

    // Insert Custom theme item right after Appearance if missing
    let customBtn = navList.querySelector('[data-agy-ct-nav="custom-theme"]');
    if (!customBtn) {
      const appearanceEl = navItems.find((el) => {
        const txt = (el.textContent || '').trim().toLowerCase();
        return txt === 'appearance' || txt === 'giao diện';
      });
      const templateEl = appearanceEl || navItems[0];

      customBtn = document.createElement(templateEl?.tagName === 'LI' ? 'li' : 'button');
      if (customBtn.tagName === 'BUTTON') customBtn.type = 'button';
      customBtn.setAttribute('data-agy-ct-injected', 'true');
      customBtn.setAttribute('data-agy-ct-nav', 'custom-theme');

      if (templateEl && templateEl.className) {
        customBtn.className = `${templateEl.className} agy-ct-nav-item`;
        customBtn.classList.remove('active', 'is-active', 'selected');
      } else {
        customBtn.className = 'agy-ct-nav-fallback agy-ct-nav-item';
      }

      customBtn.innerHTML = `<span class="agy-ct-nav-label">Custom theme</span>`;
      customBtn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        this.setCustomSettingsOpen(true);
        this.onCustomNavClick?.();
      });

      if (appearanceEl && appearanceEl.nextSibling) {
        navList.insertBefore(customBtn, appearanceEl.nextSibling);
      } else {
        navList.appendChild(customBtn);
      }
      this.injectedNavBtn = customBtn;
    }

    // Attach Settings Panel into contentPane if needed
    if (contentPane && this.settingsPanelEl && this.settingsPanelEl.parentElement !== contentPane) {
      contentPane.appendChild(this.settingsPanelEl);
    }

    if (this.isCustomSettingsOpen) {
      this.syncSettingsPaneVisibility();
    }
  }

  setCustomSettingsOpen(open) {
    this.isCustomSettingsOpen = open;
    this.syncSettingsPaneVisibility();
  }

  syncSettingsPaneVisibility() {
    if (!this.activeContentPane || !this.settingsPanelEl) return;

    const nativeChildren = Array.from(this.activeContentPane.children).filter(
      (ch) => ch !== this.settingsPanelEl
    );

    if (this.isCustomSettingsOpen) {
      nativeChildren.forEach((ch) => ch.classList.add('agy-ct-hidden-native'));
      this.settingsPanelEl.classList.add('is-open');
      this.injectedNavBtn?.classList.add('is-active');
      this.injectedNavBtn?.parentElement?.setAttribute('data-agy-ct-custom-active', 'true');
    } else {
      nativeChildren.forEach((ch) => ch.classList.remove('agy-ct-hidden-native'));
      this.settingsPanelEl.classList.remove('is-open');
      this.injectedNavBtn?.classList.remove('is-active');
      this.injectedNavBtn?.parentElement?.removeAttribute('data-agy-ct-custom-active');
    }
  }

  findChatBubbles(cfg) {
    if (cfg.customSelectors?.chatBubble) {
      return this.safeQueryAll(cfg.customSelectors.chatBubble).filter((el) => !this.isInsideInjectorUi(el));
    }

    const candidates = new Set();
    const selectors = [
      '[data-agy-chat-bubble]',
      '[data-message-author="user"]',
      '[data-message-role="user"]',
      '[data-testid*="user-message"]',
      '.user-message-bubble'
    ];
    for (const sel of selectors) {
      document.querySelectorAll(sel).forEach((el) => {
        if (!this.isInsideInjectorUi(el)) candidates.add(el);
      });
    }
    const raw = Array.from(candidates);
    // Keep only outermost bubble container so nested elements never get double borders or stacked mascots
    return raw.filter((el) => !raw.some((other) => other !== el && other.contains(el)));
  }

  decorateChatBubbles(cfg) {
    if (cfg.bubbleId === 'none') {
      document.querySelectorAll('.agy-ct-bubble-styled').forEach((el) => {
        el.classList.remove('agy-ct-bubble-styled');
        el.querySelector(':scope > .agy-ct-bubble-mascot')?.remove();
      });
      return;
    }
    const bubblePreset = BUBBLE_PRESETS.find((b) => b.id === cfg.bubbleId) || BUBBLE_PRESETS[0];
    const bubbles = this.findChatBubbles(cfg);
    const bubbleSet = new Set(bubbles);

    document.querySelectorAll('.agy-ct-bubble-styled').forEach((el) => {
      if (!bubbleSet.has(el)) {
        el.classList.remove('agy-ct-bubble-styled');
        el.querySelector(':scope > .agy-ct-bubble-mascot')?.remove();
      }
    });

    for (const el of bubbles) {
      el.classList.add('agy-ct-bubble-styled');

      let mascotHost = el.querySelector(':scope > .agy-ct-bubble-mascot');
      if (cfg.bubbleMascotEnabled && bubblePreset.mascotId) {
        const targetKey = `${bubblePreset.id}:${bubblePreset.mascotId}`;
        if (!mascotHost) {
          mascotHost = document.createElement('div');
          mascotHost.setAttribute('data-agy-ct-injected', 'true');
          el.appendChild(mascotHost);
        }
        if (mascotHost.dataset.mascotKey !== targetKey) {
          mascotHost.dataset.mascotKey = targetKey;
          mascotHost.className = `agy-ct-bubble-mascot agy-ct-bubble-mascot--${bubblePreset.mascotAlign || 'right-top'}`;
          mascotHost.innerHTML = renderMascotSvg(bubblePreset.mascotId, 'bubble');
        }
      } else if (mascotHost) {
        mascotHost.remove();
      }
    }
  }

  findChatInputContainers(cfg) {
    if (cfg.customSelectors?.chatInput) {
      return this.safeQueryAll(cfg.customSelectors.chatInput).filter((el) => !this.isInsideInjectorUi(el));
    }

    const found = new Set();
    document.querySelectorAll('[data-agy-chat-input]').forEach((el) => {
      if (!this.isInsideInjectorUi(el)) found.add(el);
    });

    if (found.size === 0) {
      // Heuristic: find composer input wrapping textarea or contenteditable with "Ask anything"
      const inputs = document.querySelectorAll('textarea, [contenteditable="true"]');
      for (const input of inputs) {
        if (this.isInsideInjectorUi(input) || this.isProtectedSurfaceEl(input)) continue;
        const ph = (input.getAttribute('placeholder') || input.getAttribute('data-placeholder') || '').toLowerCase();
        const aria = (input.getAttribute('aria-label') || '').toLowerCase();
        const box =
          input.closest('div[class*="rounded-2xl"], div[class*="rounded-xl"], div[class*="rounded-lg"], div[class*="rounded"], form, [role="region"], div[class*="composer"], div[class*="input"]') ||
          input.parentElement?.parentElement ||
          input.parentElement;
        const boxText = (box?.textContent || '').toLowerCase();
        const looksLikeChatComposer =
          ph.includes('ask') ||
          ph.includes('message') ||
          ph.includes('chat') ||
          aria.includes('chat') ||
          aria.includes('prompt') ||
          boxText.includes('ask anything') ||
          boxText.includes('@ to mention');

        if (looksLikeChatComposer && box && !this.isInsideInjectorUi(box)) {
          const rect = box.getBoundingClientRect();
          if (rect.width >= 260 && rect.height > 28 && rect.height <= window.innerHeight * 0.48) {
            found.add(box);
          }
        }
      }
    }

    return Array.from(found);
  }

  decorateChatInput(cfg) {
    const inputs = this.findChatInputContainers(cfg);
    if (cfg.inputId === 'none') {
      document.querySelectorAll('.agy-ct-input-styled').forEach((el) => {
        el.classList.remove('agy-ct-input-styled');
      });
      return inputs[0] || null;
    }
    for (const box of inputs) {
      box.classList.add('agy-ct-input-styled');
    }
    return inputs[0] || null;
  }

  /**
   * Visual Element Picker so users can point & click any Antigravity element
   * if an update changes DOM structure.
   */
  startVisualPicker(targetKey, labelText) {
    this.cancelPicker();

    const banner = document.createElement('div');
    banner.id = 'agy-ct-picker-banner';
    banner.setAttribute('data-agy-ct-injected', 'true');
    banner.innerHTML = `
      <span>🎯 Click vào phần tử <strong>${labelText}</strong> trên giao diện (Esc để huỷ)</span>
      <button type="button" class="agy-ct-btn" id="agy-ct-picker-cancel">Huỷ</button>
    `;
    document.body.appendChild(banner);

    let lastHover = null;

    const onMove = (e) => {
      const target = document.elementFromPoint(e.clientX, e.clientY);
      if (lastHover && lastHover !== target) {
        lastHover.classList.remove('agy-ct-picker-hover');
      }
      if (target && !this.isInsideInjectorUi(target)) {
        lastHover = target;
        target.classList.add('agy-ct-picker-hover');
      }
    };

    const onClick = (e) => {
      const target = e.target;
      if (target?.closest('#agy-ct-picker-banner')) return;
      e.preventDefault();
      e.stopPropagation();

      if (!this.isInsideInjectorUi(target)) {
        const selector = this.buildSelectorPath(target);
        this.onConfigPatch?.({
          customSelectors: { [targetKey]: selector }
        });
      }
      this.cancelPicker();
    };

    const onKey = (e) => {
      if (e.key === 'Escape') this.cancelPicker();
    };

    banner.querySelector('#agy-ct-picker-cancel')?.addEventListener('click', () => this.cancelPicker());
    document.addEventListener('mousemove', onMove, true);
    document.addEventListener('click', onClick, true);
    document.addEventListener('keydown', onKey, true);

    this.pickerCleanup = () => {
      lastHover?.classList.remove('agy-ct-picker-hover');
      banner.remove();
      document.removeEventListener('mousemove', onMove, true);
      document.removeEventListener('click', onClick, true);
      document.removeEventListener('keydown', onKey, true);
    };
  }

  cancelPicker() {
    if (this.pickerCleanup) {
      this.pickerCleanup();
      this.pickerCleanup = null;
    }
  }

  buildSelectorPath(el) {
    if (!el || el === document.body) return 'body';
    if (el.id && !el.id.startsWith('agy-ct-')) {
      return `#${CSS.escape(el.id)}`;
    }
    const parts = [];
    let cur = el;
    for (let depth = 0; cur && cur !== document.body && depth < 4; depth++) {
      let part = cur.tagName.toLowerCase();
      const classes = Array.from(cur.classList).filter(
        (c) => !c.startsWith('agy-ct-') && !c.includes(':') && c.length < 40
      );
      if (classes.length > 0) {
        part += `.${classes.slice(0, 2).map((c) => CSS.escape(c)).join('.')}`;
      }
      parts.unshift(part);
      cur = cur.parentElement;
    }
    return parts.join(' > ');
  }
}

