class PetStage {
  constructor({ getConfig, getCustomMedia, onPositionSave }) {
    this.getConfig = getConfig;
    this.getCustomMedia = getCustomMedia;
    this.onPositionSave = onPositionSave;

    this.stageEl = null;
    this.bodyEl = null;
    this.speechEl = null;
    this.speechTimer = null;
    this.lastPetKey = '';
    this.pos = { x: 180, y: 120 };
    this.target = { x: 180, y: 120 };
    this.dragging = false;
    this.dragMoved = false;
    this.dragOffset = { x: 0, y: 0 };
    this.motionTimer = null;
    this.rafId = null;
    this.destroyed = false;

    this.onMouseMove = (e) => {
      const cfg = this.getConfig();
      if (cfg.pet?.mode === 'follow' && !this.dragging) {
        this.target.x = Math.min(window.innerWidth - 90, Math.max(16, e.clientX + 42));
        this.target.y = Math.min(window.innerHeight - 90, Math.max(16, e.clientY - 48));
      }
    };

    window.addEventListener('mousemove', this.onMouseMove, { passive: true });
  }

  ensureMounted() {
    if (this.stageEl && document.body.contains(this.stageEl)) return;
    const el = document.createElement('div');
    el.id = 'agy-ct-pet-stage';
    el.setAttribute('data-agy-ct-injected', 'true');
    el.innerHTML = `
      <div class="agy-ct-pet-speech" aria-live="polite"></div>
      <div class="agy-ct-pet-body"></div>
    `;
    document.body.appendChild(el);
    this.stageEl = el;
    this.bodyEl = el.querySelector('.agy-ct-pet-body');
    this.speechEl = el.querySelector('.agy-ct-pet-speech');
    this.bindInteractions();
  }

  bindInteractions() {
    if (!this.stageEl) return;

    this.stageEl.addEventListener('pointerdown', (e) => {
      if (e.button !== 0) return;
      this.dragging = true;
      this.dragMoved = false;
      const rect = this.stageEl.getBoundingClientRect();
      this.dragOffset.x = e.clientX - rect.left;
      this.dragOffset.y = e.clientY - rect.top;
      this.dragStart = { x: e.clientX, y: e.clientY };
      this.stageEl.setPointerCapture?.(e.pointerId);
    });

    this.stageEl.addEventListener('pointermove', (e) => {
      if (!this.dragging) return;
      const dx = Math.abs(e.clientX - this.dragStart.x);
      const dy = Math.abs(e.clientY - this.dragStart.y);
      if (dx > 4 || dy > 4) this.dragMoved = true;

      const size = this.getConfig().pet?.size || 88;
      this.pos.x = Math.max(8, Math.min(window.innerWidth - size - 8, e.clientX - this.dragOffset.x));
      this.pos.y = Math.max(8, Math.min(window.innerHeight - size - 8, e.clientY - this.dragOffset.y));
      this.target = { ...this.pos };
      this.applyCoords();
    });

    const finishDrag = () => {
      if (!this.dragging) return;
      this.dragging = false;
      if (this.dragMoved) {
        const xPct = Math.round((this.pos.x / Math.max(1, window.innerWidth)) * 1000) / 10;
        const yPct = Math.round((this.pos.y / Math.max(1, window.innerHeight)) * 1000) / 10;
        this.onPositionSave?.({ xPct, yPct });
      } else {
        this.triggerClickReaction();
      }
    };

    this.stageEl.addEventListener('pointerup', finishDrag);
    this.stageEl.addEventListener('pointercancel', finishDrag);
  }

  triggerClickReaction() {
    const cfg = this.getConfig();
    if (!cfg.pet?.showSpeechOnClick) return;
    const petId = cfg.pet.id;
    const lang = cfg.lang === 'en' ? 'en' : 'vi';
    const bank = PET_QUIPS[petId]?.[lang] || (lang === 'en' ? ['Hello! ✨', 'Happy coding!'] : ['Xin chào! ✨', 'Code vui nhé!']);
    const line = bank[Math.floor(Math.random() * bank.length)];

    if (this.speechEl) {
      this.speechEl.textContent = line;
      this.speechEl.classList.add('is-visible');
      clearTimeout(this.speechTimer);
      this.speechTimer = setTimeout(() => {
        this.speechEl?.classList.remove('is-visible');
      }, 2800);
    }

    this.spawnBurstParticles();
  }

  spawnBurstParticles() {
    if (!this.stageEl) return;
    const rect = this.stageEl.getBoundingClientRect();
    const icons = ['✨', '⚡', '⭐', '💫'];
    for (let i = 0; i < 4; i++) {
      const sp = document.createElement('span');
      sp.className = 'agy-ct-pet-burst';
      sp.setAttribute('data-agy-ct-injected', 'true');
      sp.textContent = icons[Math.floor(Math.random() * icons.length)];
      sp.style.left = `${rect.left + rect.width * (0.25 + Math.random() * 0.5)}px`;
      sp.style.top = `${rect.top + rect.height * 0.3}px`;
      sp.style.setProperty('--dx', `${Math.round((Math.random() - 0.5) * 54)}px`);
      sp.style.setProperty('--dy', `${Math.round(-26 - Math.random() * 34)}px`);
      document.body.appendChild(sp);
      setTimeout(() => sp.remove(), 950);
    }
  }

  update() {
    const cfg = this.getConfig();
    const pet = cfg.pet || {};

    if (!cfg.enabled || !pet.enabled || pet.id === 'none') {
      this.stopMotion();
      if (this.stageEl) {
        this.stageEl.remove();
        this.stageEl = null;
        this.bodyEl = null;
        this.speechEl = null;
        this.lastPetKey = '';
      }
      return;
    }

    this.ensureMounted();
    this.stageEl.style.display = 'block';

    const size = Math.max(44, Math.min(160, Number(pet.size) || 88));
    const opacity = Math.max(0.2, Math.min(1, (pet.opacity ?? 96) / 100));
    this.stageEl.style.width = `${size}px`;
    this.stageEl.style.height = `${size}px`;
    this.stageEl.style.opacity = String(opacity);

    const customUrl = this.getCustomMedia?.().pet || '';
    const renderKey = pet.id === 'custom' ? `custom:${customUrl}` : `tpl:${pet.id}`;
    if (this.lastPetKey !== renderKey) {
      this.lastPetKey = renderKey;
      if (pet.id === 'custom' && customUrl) {
        this.bodyEl.innerHTML = `<img src="${customUrl.replace(/"/g, '&quot;')}" alt="Custom Pet" style="width:100%;height:100%;object-fit:contain;pointer-events:none;filter:drop-shadow(0 4px 10px rgba(0,0,0,0.55));" />`;
      } else {
        const tplId = MASCOT_TEMPLATES[pet.id] ? pet.id : 'rong-ngoc';
        this.bodyEl.innerHTML = renderMascotSvg(tplId, 'pet');
      }
    }

    if (!this.dragging) {
      const xPct = pet.pos?.xPct ?? 16;
      const yPct = pet.pos?.yPct ?? 14;
      const px = Math.max(8, Math.min(window.innerWidth - size - 8, (xPct / 100) * window.innerWidth));
      const py = Math.max(8, Math.min(window.innerHeight - size - 8, (yPct / 100) * window.innerHeight));
      if (pet.mode === 'float') {
        this.pos = { x: px, y: py };
        this.target = { x: px, y: py };
      } else if (this.pos.x === 180 && this.pos.y === 120) {
        this.pos = { x: px, y: py };
        this.target = { x: px, y: py };
      }
      this.applyCoords();
    }

    this.configureMotion(pet.mode);
  }

  configureMotion(mode) {
    this.stopMotion();
    if (mode === 'float') return;

    if (mode === 'roam') {
      const pickNext = () => {
        const size = this.getConfig().pet?.size || 88;
        this.target.x = 24 + Math.random() * Math.max(40, window.innerWidth - size - 48);
        this.target.y = 40 + Math.random() * Math.max(40, window.innerHeight - size - 80);
      };
      pickNext();
      this.motionTimer = setInterval(pickNext, 4500);
    }

    const step = () => {
      if (this.destroyed) return;
      if (!this.dragging) {
        const dx = this.target.x - this.pos.x;
        const dy = this.target.y - this.pos.y;
        const ease = mode === 'follow' ? 0.045 : 0.015;
        if (Math.abs(dx) > 0.4 || Math.abs(dy) > 0.4) {
          this.pos.x += dx * ease;
          this.pos.y += dy * ease;
          this.applyCoords();
        }
      }
      this.rafId = requestAnimationFrame(step);
    };
    this.rafId = requestAnimationFrame(step);
  }

  applyCoords() {
    if (!this.stageEl) return;
    this.stageEl.style.left = `${Math.round(this.pos.x)}px`;
    this.stageEl.style.top = `${Math.round(this.pos.y)}px`;
  }

  stopMotion() {
    if (this.motionTimer) {
      clearInterval(this.motionTimer);
      this.motionTimer = null;
    }
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
  }

  destroy() {
    this.destroyed = true;
    this.stopMotion();
    clearTimeout(this.speechTimer);
    window.removeEventListener('mousemove', this.onMouseMove);
    this.stageEl?.remove();
    this.stageEl = null;
  }
}

  // ===== ui/sticker-layer.js =====
/**
 * Decorative Sticker Manager.
 * Anchors stickers cleanly onto slots (input-top-right like Image 2, input-top-left,
 * greeting-badge, sidebar-bottom-right) or free draggable positions.
 */
class StickerLayer {
  constructor({ getConfig, getCustomMedia, findInputBox, onStickerMove }) {
    this.getConfig = getConfig;
    this.getCustomMedia = getCustomMedia;
    this.findInputBox = findInputBox;
    this.onStickerMove = onStickerMove;

    this.nodes = new Map();
    this.repositionHandler = () => this.repositionAll();
    window.addEventListener('resize', this.repositionHandler);
  }

  update() {
    const cfg = this.getConfig();
    const stickersCfg = cfg.stickers || { enabled: false, items: [] };

    if (!cfg.enabled || !stickersCfg.enabled || !Array.isArray(stickersCfg.items) || stickersCfg.items.length === 0) {
      this.clearAll();
      return;
    }

    const activeKeys = new Set();
    const customUrl = this.getCustomMedia?.().sticker || '';

    stickersCfg.items.forEach((item, index) => {
      const key = `${index}:${item.id}`;
      activeKeys.add(key);

      let node = this.nodes.get(key);
      if (!node) {
        node = this.createNode(index, item, customUrl);
        this.nodes.set(key, node);
        document.body.appendChild(node);
      } else {
        const expectedRender = item.id === 'custom' ? `custom:${customUrl}` : `tpl:${item.id}`;
        if (node.dataset.renderKey !== expectedRender) {
          node.dataset.renderKey = expectedRender;
          node.innerHTML = this.renderContent(item.id, customUrl);
        }
      }

      const size = Math.max(28, Math.min(120, Number(item.size) || 52));
      const opacity = Math.max(0.2, Math.min(1, (item.opacity ?? 95) / 100));
      node.style.width = `${size}px`;
      node.style.height = `${size}px`;
      node.style.opacity = String(opacity);
      node.classList.toggle('has-glow', item.glow !== false);
      node.dataset.index = String(index);
    });

    for (const [key, node] of this.nodes.entries()) {
      if (!activeKeys.has(key)) {
        node.remove();
        this.nodes.delete(key);
      }
    }

    this.repositionAll();
  }

  renderContent(id, customUrl) {
    if (id === 'custom' && customUrl) {
      return `<img src="${customUrl.replace(/"/g, '&quot;')}" alt="Custom Sticker" style="width:100%;height:100%;object-fit:contain;pointer-events:none;" />`;
    }
    const tplId = STICKER_TEMPLATES[id] ? id : 'trang-sao';
    return renderStickerSvg(tplId);
  }

  createNode(index, item, customUrl) {
    const node = document.createElement('div');
    node.className = 'agy-ct-sticker-node';
    node.setAttribute('data-agy-ct-injected', 'true');
    node.dataset.index = String(index);
    node.dataset.renderKey = item.id === 'custom' ? `custom:${customUrl}` : `tpl:${item.id}`;
    node.title = 'Kéo để di chuyển sticker';
    node.innerHTML = this.renderContent(item.id, customUrl);

    let dragging = false;
    let offset = { x: 0, y: 0 };

    node.addEventListener('pointerdown', (e) => {
      if (e.button !== 0) return;
      dragging = true;
      const rect = node.getBoundingClientRect();
      offset = { x: e.clientX - rect.left, y: e.clientY - rect.top };
      node.setPointerCapture?.(e.pointerId);
    });

    node.addEventListener('pointermove', (e) => {
      if (!dragging) return;
      const size = parseFloat(node.style.width) || 52;
      const x = Math.max(6, Math.min(window.innerWidth - size - 6, e.clientX - offset.x));
      const y = Math.max(6, Math.min(window.innerHeight - size - 6, e.clientY - offset.y));
      node.style.left = `${Math.round(x)}px`;
      node.style.top = `${Math.round(y)}px`;
    });

    const endDrag = () => {
      if (!dragging) return;
      dragging = false;
      const rect = node.getBoundingClientRect();
      const xPct = Math.round((rect.left / Math.max(1, window.innerWidth)) * 1000) / 10;
      const yPct = Math.round((rect.top / Math.max(1, window.innerHeight)) * 1000) / 10;
      const idx = Number(node.dataset.index);
      this.onStickerMove?.(idx, { slot: 'free', pos: { xPct, yPct } });
    };

    node.addEventListener('pointerup', endDrag);
    node.addEventListener('pointercancel', endDrag);
    return node;
  }

  repositionAll() {
    const cfg = this.getConfig();
    const items = cfg.stickers?.items || [];
    const inputEl = this.findInputBox?.();
    const inputRect = inputEl ? inputEl.getBoundingClientRect() : null;
    const sidebarEl = document.querySelector('.agy-ct-surface-sidebar');
    const sidebarRect = sidebarEl ? sidebarEl.getBoundingClientRect() : null;

    items.forEach((item, index) => {
      const key = `${index}:${item.id}`;
      const node = this.nodes.get(key);
      if (!node) return;
      const size = Math.max(28, Math.min(120, Number(item.size) || 52));
      let x = 0;
      let y = 0;

      if (item.slot === 'input-top-right' && inputRect && inputRect.width > 40) {
        x = inputRect.right - size * 0.72;
        y = inputRect.top - size * 0.56;
      } else if (item.slot === 'input-top-left' && inputRect && inputRect.width > 40) {
        x = inputRect.left - size * 0.28;
        y = inputRect.top - size * 0.56;
      } else if (item.slot === 'sidebar-bottom-right' && sidebarRect && sidebarRect.width > 40) {
        x = sidebarRect.right - size - 10;
        y = sidebarRect.bottom - size - 14;
      } else if (item.slot === 'greeting-badge') {
        const xBase = inputRect ? inputRect.left + inputRect.width * 0.78 : window.innerWidth * 0.72;
        const yBase = inputRect ? Math.max(60, inputRect.top - 110) : window.innerHeight * 0.44;
        x = xBase;
        y = yBase;
      } else if (item.slot === 'free' && item.pos) {
        x = (item.pos.xPct / 100) * window.innerWidth;
        y = (item.pos.yPct / 100) * window.innerHeight;
      } else {
        // Fallback near bottom-right composer area
        x = window.innerWidth - size - 36;
        y = window.innerHeight - size - 120;
      }

      x = Math.max(4, Math.min(window.innerWidth - size - 4, x));
      y = Math.max(4, Math.min(window.innerHeight - size - 4, y));
      node.style.left = `${Math.round(x)}px`;
      node.style.top = `${Math.round(y)}px`;
    });
  }

  clearAll() {
    for (const node of this.nodes.values()) {
      node.remove();
    }
    this.nodes.clear();
  }

  destroy() {
    window.removeEventListener('resize', this.repositionHandler);
    this.clearAll();
  }
}

